        assertThat(changedArea).isNotEqualTo(original);
    }

    @Test
    void differentGroupProducesDifferentFingerprint() {
        assertThat(Fingerprint.ofPlan("req-1", 10L, "G1", linesA()))
                .isNotEqualTo(Fingerprint.ofPlan("req-1", 10L, "G2", linesA()));
