            long planId,
            String groupCode,
            long turnNo,
            int versionNo,
            String status,
            long availableCubicMeter,
            String requestId,
            String fingerprint,
            Instant publishedAt,
            List<PlanLineResponse> lines) {
    }

    /** 斗口计划明细，按斗口编号升序；权重四位小数，计划量单位立方米。 */
    public record PlanLineResponse(
            String outletCode,
            long areaSquareMeter,
            BigDecimal weight,
            long planCubicMeter) {
    }
}

