                "irr_settlement", "irr_carryover", "irr_late_meter_event");
        for (String table : tables) {
            Integer count = jdbc.queryForObject(
                    "SELECT COUNT(1) FROM INFORMATION_SCHEMA.TABLES WHERE LOWER(TABLE_NAME) = ?",
                    Integer.class, table);
