                        .content("""
                                {"eventId":"http-m1","groupCode":"G-HTTP","outletCode":"D001",
                                 "turnNo":3000,"deliveredCubicMeter":999}
                                """))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.duplicate").value(true))
                .andExpect(jsonPath("$.deliveredCubicMeter").value(2));

